struct TokenBucket {
    capacity: u32,
    tokens: f64,
    refill_rate: f64,
    last_refill: Instant,
}

impl TokenBucket {
    fn new(capacity: u32, refill_rate: f64) -> Self {
        TokenBucket { capacity, tokens: capacity as f64, refill_rate, last_refill: Instant::now() }
    }
    fn allow(&mut self) -> bool {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.refill_rate).min(self.capacity as f64);
        self.last_refill = now;
        if self.tokens >= 1.0 { self.tokens -= 1.0; true } else { false }
    }
}

struct BstNode {
    val: i32,
    left: Option<Box<BstNode>>,
    right: Option<Box<BstNode>>,
}

impl BstNode {
    fn new(val: i32) -> Self { BstNode { val, left: None, right: None } }
    fn insert(&mut self, val: i32) {
        if val < self.val {
            match self.left {
                Some(ref mut node) => node.insert(val),
                None => self.left = Some(Box::new(BstNode::new(val))),
            }
        } else {
            match self.right {
                Some(ref mut node) => node.insert(val),
                None => self.right = Some(Box::new(BstNode::new(val))),
            }
        }
    }
    fn search(&self, val: i32) -> bool {
        if val == self.val { true }
        else if val < self.val { self.left.as_ref().map_or(false, |n| n.search(val)) }
        else { self.right.as_ref().map_or(false, |n| n.search(val)) }
    }
}

use std::collections::HashMap;

type Callback = Box<dyn Fn(&str)>;

struct EventEmitter {
    listeners: HashMap<String, Vec<Callback>>,
}

impl EventEmitter {
    fn new() -> Self { EventEmitter { listeners: HashMap::new() } }
    fn on(&mut self, event: &str, cb: Callback) {
        self.listeners.entry(event.to_string()).or_default().push(cb);
    }
    fn emit(&self, event: &str, data: &str) {
        if let Some(cbs) = self.listeners.get(event) {
            for cb in cbs { cb(data); }
        }
    }
}

trait SortStrategy {
    fn sort(&self, data: &mut Vec<i32>);
}

struct BubbleSort;
impl SortStrategy for BubbleSort {
    fn sort(&self, data: &mut Vec<i32>) {
        let n = data.len();
        for i in 0..n {
            for j in 0..n - 1 - i {
                if data[j] > data[j + 1] { data.swap(j, j + 1); }
            }
        }
    }
}

struct InsertionSort;
impl SortStrategy for InsertionSort {
    fn sort(&self, data: &mut Vec<i32>) {
        for i in 1..data.len() {
            let key = data[i];
            let mut j = i;
            while j > 0 && data[j - 1] > key { data[j] = data[j - 1]; j -= 1; }
            data[j] = key;
        }
    }
}

fn sort_with(data: &mut Vec<i32>, strategy: &dyn SortStrategy) {
    strategy.sort(data);
}

fn parse_all(inputs: &[&str]) -> Result<Vec<i32>, std::num::ParseIntError> {
