}

fn parse_with_fallback(inputs: &[&str]) -> (Vec<i32>, Vec<String>) {
    let mut ok = Vec::new();
    let mut errs = Vec::new();
    for s in inputs {
        match s.parse::<i32>() {
            Ok(n) => ok.push(n),
            Err(e) => errs.push(format!("{}: {}", s, e)),
        }
    }
    (ok, errs)
}

