struct Pipeline<T> {
    stages: Vec<Box<dyn Fn(T) -> T>>,
}

impl<T> Pipeline<T> {
    fn new() -> Self { Pipeline { stages: Vec::new() } }
    fn add_stage(&mut self, f: impl Fn(T) -> T + 'static) {
        self.stages.push(Box::new(f));
    }
    fn execute(&self, mut input: T) -> T {
        for stage in &self.stages {
            input = stage(input);
        }
        input
    }
}

